#!/usr/bin/env node
/*
 * frontx-ui-grid-css: writes the Grid step rules for a config.
 *
 *   frontx-ui-grid-css [--kit-default] <config.json|config.mjs|config.js> <output.css>
 *
 * `@container` conditions cannot read `var()`, so every container step width
 * has to be a literal in CSS; this command turns a GridConfig into those
 * rules. The kit's grid-steps.css is this command's output for the default
 * config, regenerated by `npm run grid:css -w @gears-frontx/ui-kit` and kept
 * equal by a test. Rules are scoped by the config name through `data-fx-grid`,
 * never by a CSS Module class, so a custom config's CSS coexists with the
 * default.
 *
 * `default` is the kit's own scope: the command refuses a config under that
 * name unless --kit-default is given. The flag is public on the installed bin
 * and is meant for regenerating the kit's own stylesheet, which the kit's
 * `grid:css` script and the consumer acceptance do; it guards against a
 * custom config accidentally shadowing the shipped rules, not against doing
 * so on purpose.
 *
 * The generator and the config checks it runs live in the component
 * directory. The build copies grid-css.mjs and grid-config-check.mjs flat
 * into dist/ beside the bin and rewrites the one import specifier below to
 * './grid-css.mjs', a rewrite buildPlugin.ts guards by refusing to copy when
 * this specifier text moves, so the specifier stays as written unless the
 * copy step changes with it. The command stays in scripts/ because it alone
 * needs the Node builtins the component source may not import.
 */
import { readFile, stat, writeFile } from 'node:fs/promises';
import { extname, resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

import { generateGridCss } from '../src/components/grid/grid-css.mjs';

const USAGE = 'Usage: frontx-ui-grid-css [--kit-default] <config.json|config.mjs|config.js> <output.css>';

async function main() {
  const args = process.argv.slice(2);
  const kitDefault = args.includes('--kit-default');
  const positionals = args.filter(argument => argument !== '--kit-default');
  // An explicit help request succeeds: the usage text on stdout, exit 0.
  if (args.includes('--help') || args.includes('-h')) {
    console.log(USAGE);
    return;
  }
  // One option and two positionals: any other --word is a mistyped invocation,
  // and any other arity has no reading, so both stop here instead of surfacing
  // later as a missing or misread file. Apart from -h, a single dash stays a
  // path character; a path that starts with -- is passed as ./--name.
  if (args.some(argument => argument.startsWith('--') && argument !== '--kit-default') || positionals.length !== 2) {
    throw new Error(USAGE);
  }
  const [input, output] = positionals;
  const path = resolve(input);
  // The output is written as CSS: the same file would replace the config.
  // Checked before anything is read or written: by path, and for an existing
  // output by filesystem identity (dev + ino), which catches a symlink, a hard
  // link or a case alias. A missing output cannot be the config.
  const sameFileError = new Error(`Output path ${output} is the config file; give the CSS its own path`);
  if (path === resolve(output)) throw sameFileError;
  const [configStat, outputStat] = await Promise.all([stat(path).catch(() => null), stat(resolve(output)).catch(() => null)]);
  if (configStat && outputStat && configStat.dev === outputStat.dev && configStat.ino === outputStat.ino) throw sameFileError;
  const extension = extname(path);
  if (extension !== '.json' && extension !== '.mjs' && extension !== '.js') {
    throw new Error('Grid config must be a .json file or an ES module (.mjs, .js) with a default export');
  }
  let config;
  if (extension === '.json') {
    config = JSON.parse(await readFile(path, 'utf8'));
  } else {
    const module = await import(pathToFileURL(path).href);
    if (!('default' in module)) throw new Error(`Grid config module ${input} has no default export`);
    config = module.default;
  }
  await writeFile(resolve(output), generateGridCss(config, { allowDefaultName: kitDefault }));
}

main().catch(error => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});
